def is_type_B(N):
    if N == 1:
        return False # Type A

    # L[n] is True if starting at n is a P-position (Losing position for current player), 
    # False if N-position (Winning position).
    L = {} 

    # Iterate backwards from N-1 down to 1
    for n in range(N - 1, 0, -1):
        moves = []

        # Check move n+1
        if n + 1 <= N:
            moves.append(n + 1)

        # Check move 2n
        if 2 * n <= N:
            moves.append(2 * n)

        can_win_immediately = False

        # Check for immediate win (moving to N)
        if N in moves:
            can_win_immediately = True

        if can_win_immediately:
            L[n] = False # N-position (Winning)
        else:
            # General case: check outcomes of moves < N

            # Check if there is a move to a P-position (Losing state for opponent)
            is_P_position = False
            for m in moves:
                if m < N:
                    # L[m] must be defined since we iterate backwards
                    if L[m] is True: # Found a move to a P-position
                        is_P_position = True
                        break
                # Note: If m=N, it would have been caught by can_win_immediately, 
                # but since we excluded it here, m < N always holds.

            if is_P_position:
                L[n] = False # N-position (Winning)
            else:
                # All moves lead to N-positions
                L[n] = True # P-position (Losing)

    # N is Type B if starting at 1 is a P-position (L[1] is True)
    return L[1]

# Calculate up to N=500 to find patterns and the required value.
max_N = 500
type_b_numbers = []
for N in range(1, max_N + 1):
    if is_type_B(N):
        type_b_numbers.append(N)

print(f"List of Type B numbers up to {max_N}:")
print(type_b_numbers)

